insert into public.blog_yazilari (id,kategori,tarih,okuma_suresi,gorsel,icerik) values (29,'trends','2026-10-28',5,'/img-cat-ilac.jpg','{"tr":{"title":"Gen İlaç Azerbaycan''da fabrika açtı: 113,9 milyon manatlık yatırım","excerpt":"Gen İlaç ortaklığındaki Gen Pharma Caucasus, Bakü yakınındaki Pirallahı Sanayi Parkı''nda yıllık 60 milyon kutu kapasiteli ilaç fabrikasını açtı.","content":["Açılış — Türk ilaç şirketi GEN İlaç ve Sağlık Ürünleri''nin Azerbaycan''daki ortak girişimi Gen Pharma Caucasus Manufacturing Operations MMC''nin ilaç üretim tesisi, 5 Ekim 2026''da Bakü yakınındaki Pirallahı Sanayi Parkı''nda Azerbaycan Cumhurbaşkanı İlham Aliyev''in katılımıyla açıldı. Törende Ekonomi Bakanı Mikayıl Cabbarov sanayi bölgeleri hakkında, şirketin kurucusu ve GEN Yönetim Kurulu Başkanı Abidin Gülmüş ise tesis hakkında bilgi verdi. Temeli 7 Aralık 2023''te atılan tesis, bir niyet beyanı değil, faaliyete geçmiş bir üretim yatırımı. GEN, KAP açıklamasında tesisi Azerbaycan''ın en büyük ilaç üretim tesisi olarak tanımladı.","Ortaklar — Azerbaycan resmi kaynaklarına göre şirketin %66''sı GEN İlaç ve Sağlık Ürünleri Sanayi A.Ş.''ye, %29''u Ekonomi Bakanlığı''na bağlı Azerbaycan İş Geliştirme Fonu''na (Azərbaycan Biznesinin İnkişafı Fondu), %5''i ise Türk şirketi SIA Pharmaceuticals''a ait. Ortaklık, 31 Temmuz 2023''te Azerbaycan Yatırım Şirketi (AİŞ) ile GEN arasında imzalanan ortaklık ve ortak katılım anlaşmasıyla başladı; GEN''in KAP açıklaması da ortak olarak Azerbaycan Yatırım Şirketi''ni (AIC) anıyor. Şirket, 2023''te Pirallahı Sanayi Parkı rezidenti statüsü aldı.","Yatırım — Projenin toplam değeri 113,9 milyon manat. Finansman; özel yatırım, Azerbaycan İş Geliştirme Fonu''nun 13,2 milyon manatlık yatırımı ve 10 milyon manatlık imtiyazlı krediden oluşuyor. Interfax, 5 Ekim kuruyla (1 dolar = 1,70 manat) bu tutarı yaklaşık 67 milyon dolar olarak verdi. Park rezidenti olarak şirket, 7 milyon manatı aşan KDV ve gümrük vergisi muafiyetinden yararlanıyor. Proje ilk planlardan büyüdü: Aralık 2023''teki temel atma töreninde yatırım 59,3 milyon manat, istihdam 165 kişi olarak açıklanmıştı.","Kapasite ve istihdam — 5,2 hektarlık alana kurulan tesisin yıllık kapasitesi 60 milyon kutu ilaç; bunun içinde 2,5 milyar tablet ve kapsül yer alıyor. Fabrikada 178 kalıcı iş yeri bulunuyor. Üretimde ABD, Japonya, Almanya, İsviçre, Çin, Danimarka, İsveç ve Türkiye''deki üreticilerin ekipmanları kullanılıyor. Tesisin Karabağ Üniversitesi ve Azerbaycan Tıp Üniversitesi için resmi eğitim üssü olması da planlanıyor.","Üretilen ilaçlar — Resmi açıklamalara göre tesiste kardiyoloji, nöroloji, üroloji, diyabetoloji ve gastroenteroloji alanlarında ilaçlar ile ağrı kesiciler ve antibiyotikler üretilecek. Şirket beş yıl içinde 500''den fazla ilacın üretimini yerelleştirmeyi hedefliyor; Türk basınına yansıyan bilgilere göre 2027''ye kadar 50 ilacın üretime alınması planlanıyor. Ürün bazında tam liste açıklanmadı. GEN''in sitesindeki Azerbaycan ürünleri sayfası (Haziran 2025 arşiv kaydında 27 ürün) şirketin bu ülke için listelediği ürünleri gösteriyor; bu liste fabrikanın üretim listesi değildir.","Pazar ve ihracat — Genel Müdür Farid Aliyev''e göre öncelik iç pazar ve iç talebin mümkün olduğunca karşılanması. İhracat için Özbekistan, Kazakistan ve Gürcistan öne çıkıyor. Pirallahı Sanayi Parkı, 2016''da cumhurbaşkanlığı kararnamesiyle ilaç sanayisini geliştirmek ve ithalata bağımlılığı azaltmak amacıyla kuruldu; parkta altı rezident kayıtlı. CSC olarak Azerbaycan pazarındaki bu gelişmeleri yakından takip ediyoruz.","Kaynak: APA (05.10.2026); Trend (05.10.2026); Report.az (05.10.2026); AZERTAC (05.10.2026); Borsagündem, GEN İlaç KAP açıklaması (05.10.2026); Interfax (06.10.2026); DHA (06.10.2026); Anadolu Ajansı / Daily Sabah (07.12.2023); Trend (07.12.2023); Azerbaycan Devlet Vergi Servisi, taxes.gov.az (31.07.2023); genilac.com.tr Azerbaycan ürün sayfası, Internet Archive kaydı (21.06.2025)."]},"en":{"title":"Gen Ilac opens AZN 113.9m drug plant in Azerbaijan''s Pirallahi park","excerpt":"Gen Pharma Caucasus, a Turkish-Azerbaijani joint venture led by Gen Ilac, opened a 60-million-box-a-year drug plant in Pirallahi Industrial Park.","content":["Opening — The pharmaceutical plant of Gen Pharma Caucasus Manufacturing Operations LLC, the Azerbaijani joint venture of Turkish drugmaker GEN Ilac ve Saglik Urunleri, opened on 5 October 2026 in Pirallahi Industrial Park near Baku, with President Ilham Aliyev in attendance. Economy Minister Mikayil Jabbarov briefed the President on the industrial zones, and founder and GEN board chairman Abidin Gulmus presented the plant. Construction began with a groundbreaking on 7 December 2023, so this is an operating production facility, not a memorandum or a plan. In its KAP disclosure, GEN described it as Azerbaijan’s largest pharmaceutical manufacturing facility.","Partners — According to official Azerbaijani sources, GEN Ilac ve Saglik Urunleri Sanayi A.S. holds 66% of the company, the Azerbaijan Business Development Fund under the Ministry of Economy holds 29%, and Turkish company SIA Pharmaceuticals holds 5%. The partnership began with a partnership and joint participation agreement signed on 31 July 2023 between GEN and the Azerbaijan Investment Company (AIC); GEN’s KAP disclosure also names AIC as its partner. The company received resident status in Pirallahi Industrial Park in 2023.","Investment — The total project value is AZN 113.9 million, financed through private investment, AZN 13.2 million from the Azerbaijan Business Development Fund and AZN 10 million in concessional loans. Interfax put the figure at about USD 67 million at the 5 October rate of AZN 1.70 per dollar. As a park resident, the company is exempt from more than AZN 7 million in VAT and customs duties. The project grew from its original plan: at the December 2023 groundbreaking the investment was given as AZN 59.3 million, with 165 jobs.","Capacity and jobs — The plant occupies 5.2 hectares and has an annual capacity of 60 million boxes of medicines, including 2.5 billion tablets and capsules. It provides 178 permanent jobs. Its equipment comes from manufacturers in the US, Japan, Germany, Switzerland, China, Denmark, Sweden and Turkiye. The site is also planned as an official training base for Karabakh University and Azerbaijan Medical University.","Medicines produced — According to official statements, the plant will make cardiology, neurology, urology, diabetology and gastroenterology medicines, as well as painkillers and antibiotics. The company aims to localise production of more than 500 medicines within five years, and Turkish media reported a target of 50 medicines in production by 2027. A product-by-product list has not been published. The Azerbaijan page on GEN’s website (27 products in a June 2025 archive snapshot) shows products the company lists for that country; it is not the plant’s production list.","Market and exports — General Director Farid Aliyev said the primary focus is the domestic market, meeting local demand as fully as possible. Uzbekistan, Kazakhstan and Georgia are named as export destinations. Pirallahi Industrial Park was set up by presidential decree in 2016 to develop the pharmaceutical industry and reduce import dependence; six residents are registered there. At CSC, we are closely following these developments in the Azerbaijani market.","Source: APA (05.10.2026); Trend (05.10.2026); Report.az (05.10.2026); AZERTAC (05.10.2026); Borsagundem, GEN Ilac KAP disclosure (05.10.2026); Interfax (06.10.2026); DHA (06.10.2026); Anadolu Agency / Daily Sabah (07.12.2023); Trend (07.12.2023); State Tax Service of Azerbaijan, taxes.gov.az (31.07.2023); genilac.com.tr Azerbaijan product page, Internet Archive snapshot (21.06.2025)."]},"ru":{"title":"Gen İlaç открыла в Азербайджане завод лекарств за 113,9 млн манатов","excerpt":"Турецко-азербайджанское СП Gen Pharma Caucasus открыло в Пираллахинском промпарке завод мощностью 60 млн упаковок лекарств в год. Детали проекта.","content":["Открытие — 5 октября 2026 года в Пираллахинском промышленном парке под Баку при участии президента Ильхама Алиева открылся фармацевтический завод ООО Gen Pharma Caucasus Manufacturing Operations — совместного предприятия турецкой компании GEN İlaç ve Sağlık Ürünleri. Министр экономики Микаил Джаббаров рассказал президенту о промышленных зонах, а основатель предприятия и председатель совета директоров GEN Абидин Гюльмюш представил завод. Фундамент был заложен 7 декабря 2023 года, то есть речь идёт о действующем производстве, а не о меморандуме или планах. В раскрытии на KAP компания GEN назвала его крупнейшим фармацевтическим производством Азербайджана.","Партнёры — По данным официальных азербайджанских источников, 66% предприятия принадлежит GEN İlaç ve Sağlık Ürünleri Sanayi A.Ş., 29% — Фонду развития бизнеса Азербайджана при Министерстве экономики, 5% — турецкой компании SIA Pharmaceuticals. Партнёрство началось с соглашения о партнёрстве и совместном участии, подписанного 31 июля 2023 года между GEN и Азербайджанской инвестиционной компанией (АИК); в раскрытии GEN на KAP партнёром также названа АИК. Статус резидента Пираллахинского промпарка компания получила в 2023 году.","Инвестиции — Общая стоимость проекта — 113,9 млн манатов. Финансирование включает частные инвестиции, 13,2 млн манатов от Фонда развития бизнеса и 10 млн манатов льготного кредита. По курсу на 5 октября (1,70 маната за доллар) Interfax оценил сумму примерно в 67 млн долларов. Как резидент парка компания освобождена от НДС и таможенных пошлин на сумму свыше 7 млн манатов. Проект вырос по сравнению с первоначальным планом: на закладке фундамента в декабре 2023 года объём инвестиций называли в 59,3 млн манатов, а число рабочих мест — 165.","Мощность и рабочие места — Завод площадью 5,2 га рассчитан на выпуск 60 млн упаковок лекарств в год, в том числе 2,5 млрд таблеток и капсул. На предприятии 178 постоянных рабочих мест. Оборудование поставили производители из США, Японии, Германии, Швейцарии, Китая, Дании, Швеции и Турции. Завод также планируется использовать как официальную учебную базу для Карабахского университета и Азербайджанского медицинского университета.","Выпускаемые препараты — Согласно официальным данным, завод будет выпускать препараты для кардиологии, неврологии, урологии, диабетологии и гастроэнтерологии, а также обезболивающие и антибиотики. Компания планирует в течение пяти лет локализовать производство более 500 препаратов; по данным турецких СМИ, к 2027 году в производство планируется запустить 50 препаратов. Полный перечень продукции не опубликован. Страница продукции для Азербайджана на сайте GEN (27 позиций в архивной копии июня 2025 года) показывает препараты, которые компания указывает для этой страны; это не производственный перечень завода.","Рынок и экспорт — По словам генерального директора Фарида Алиева, приоритет — внутренний рынок и максимально полное удовлетворение местного спроса. В числе экспортных направлений названы Узбекистан, Казахстан и Грузия. Пираллахинский промышленный парк создан указом президента в 2016 году для развития фармацевтической отрасли и снижения зависимости от импорта; в нём зарегистрированы шесть резидентов. CSC внимательно следит за этими изменениями на рынке Азербайджана.","Источник: APA (05.10.2026); Trend (05.10.2026); Report.az (05.10.2026); АЗЕРТАДЖ (05.10.2026); Borsagündem, раскрытие GEN İlaç на KAP (05.10.2026); Interfax (06.10.2026); DHA (06.10.2026); Anadolu / Daily Sabah (07.12.2023); Trend (07.12.2023); Государственная налоговая служба Азербайджана, taxes.gov.az (31.07.2023); страница продукции для Азербайджана на genilac.com.tr, архив Internet Archive (21.06.2025)."]},"kz":{"title":"Gen İlaç Әзірбайжанда 113,9 млн манаттық дәрі зауытын ашты","excerpt":"Түрік-әзірбайжан бірлескен кәсіпорны Gen Pharma Caucasus Пираллахы өнеркәсіп паркінде жылына 60 млн қорап дәрі шығаратын зауыт ашты. Толығырақ.","content":["Ашылуы — 2026 жылғы 5 қазанда Баку маңындағы Пираллахы өнеркәсіп паркінде Президент Ильхам Әлиевтің қатысуымен түрік GEN İlaç ve Sağlık Ürünleri компаниясының бірлескен кәсіпорны Gen Pharma Caucasus Manufacturing Operations ЖШС-ның фармацевтикалық зауыты ашылды. Экономика министрі Микаил Джаббаров Президентке өнеркәсіп аймақтары туралы, кәсіпорынның негізін салушы әрі GEN директорлар кеңесінің төрағасы Абидин Гюльмюш зауыт туралы баяндады. Іргетасы 2023 жылғы 7 желтоқсанда қаланған нысан — меморандум не жоспар емес, жұмыс істеп тұрған өндіріс. GEN компаниясы KAP хабарламасында оны Әзірбайжандағы ең ірі дәрі өндірісі деп атады.","Серіктестер — Әзірбайжанның ресми дереккөздеріне сәйкес кәсіпорынның 66%-ы GEN İlaç ve Sağlık Ürünleri Sanayi A.Ş. компаниясына, 29%-ы Экономика министрлігі жанындағы Әзірбайжан бизнесін дамыту қорына, 5%-ы түрік SIA Pharmaceuticals компаниясына тиесілі. Серіктестік 2023 жылғы 31 шілдеде GEN мен Әзірбайжан инвестициялық компаниясы (AIC) арасында қол қойылған серіктестік және бірлескен қатысу туралы келісімнен басталды; GEN-нің KAP хабарламасында да серіктес ретінде AIC аталады. Компания Пираллахы өнеркәсіп паркінің резиденті мәртебесін 2023 жылы алды.","Инвестиция — Жобаның жалпы құны 113,9 млн манат. Қаржыландыру жеке инвестициядан, Әзірбайжан бизнесін дамыту қорының 13,2 млн манаттық инвестициясынан және 10 млн манаттық жеңілдетілген несиеден тұрады. Interfax 5 қазандағы бағам бойынша (1 доллар = 1,70 манат) бұл соманы шамамен 67 млн доллар деп көрсетті. Парк резиденті ретінде компания 7 млн манаттан астам ҚҚС пен кедендік баждан босатылған. Жоба бастапқы жоспардан ұлғайды: 2023 жылғы желтоқсандағы іргетас қалау рәсімінде инвестиция 59,3 млн манат, жұмыс орны 165 деп жарияланған еді.","Қуаты және жұмыс орындары — 5,2 гектар аумақтағы зауыттың жылдық қуаты 60 млн қорап дәрі, оның ішінде 2,5 млрд таблетка мен капсула. Кәсіпорында 178 тұрақты жұмыс орны бар. Жабдықтар АҚШ, Жапония, Германия, Швейцария, Қытай, Дания, Швеция және Түркия өндірушілерінен алынған. Зауытты Қарабақ университеті мен Әзірбайжан медицина университеті үшін ресми оқу базасы ретінде пайдалану да жоспарланған.","Шығарылатын дәрілер — Ресми мәліметке сәйкес зауыт кардиология, неврология, урология, диабетология және гастроэнтерология дәрілерін, сондай-ақ ауырсынуды басатын препараттар мен антибиотиктер шығарады. Компания бес жыл ішінде 500-ден астам дәрінің өндірісін оқшаулауды көздейді; түрік БАҚ-ына сәйкес 2027 жылға дейін 50 дәріні өндіріске енгізу жоспарланған. Өнімдердің толық тізімі жарияланбаған. GEN сайтындағы Әзірбайжан өнімдері беті (2025 жылғы маусымдағы мұрағат көшірмесінде 27 өнім) компанияның осы елге арналған өнімдерін көрсетеді; бұл зауыттың өндірістік тізімі емес.","Нарық және экспорт — Бас директор Фарид Әлиевтің айтуынша, басымдық — ішкі нарық және жергілікті сұранысты барынша толық қамтамасыз ету. Экспорт бағыттары ретінде Өзбекстан, Қазақстан және Грузия аталды. Пираллахы өнеркәсіп паркі фармацевтика саласын дамыту және импортқа тәуелділікті азайту мақсатында 2016 жылы Президент жарлығымен құрылған; паркте алты резидент тіркелген. CSC ретінде біз Әзірбайжан нарығындағы бұл өзгерістерді мұқият қадағалап отырмыз.","Дереккөз: APA (05.10.2026); Trend (05.10.2026); Report.az (05.10.2026); АЗЕРТАДЖ (05.10.2026); Borsagündem, GEN İlaç компаниясының KAP хабарламасы (05.10.2026); Interfax (06.10.2026); DHA (06.10.2026); Anadolu / Daily Sabah (07.12.2023); Trend (07.12.2023); Әзірбайжан Мемлекеттік салық қызметі, taxes.gov.az (31.07.2023); genilac.com.tr сайтындағы Әзірбайжан өнімдері беті, Internet Archive мұрағаты (21.06.2025)."]},"az":{"title":"Gen İlaç Pirallahıda 113,9 milyon manatlıq dərman zavodu açdı","excerpt":"Türkiyə-Azərbaycan birgə müəssisəsi Gen Pharma Caucasus Pirallahı Sənaye Parkında ildə 60 milyon qutu dərman istehsal edəcək zavodu istifadəyə verdi.","content":["Açılış — 2026-cı il oktyabrın 5-də Bakı yaxınlığındakı Pirallahı Sənaye Parkında Prezident İlham Əliyevin iştirakı ilə Türkiyənin GEN İlaç ve Sağlık Ürünleri şirkətinin birgə müəssisəsi olan Gen Pharma Caucasus Manufacturing Operations MMC-nin dərman istehsalı zavodu açıldı. İqtisadiyyat naziri Mikayıl Cabbarov dövlət başçısına sənaye zonaları barədə, müəssisənin təsisçisi və GEN-in İdarə Heyətinin sədri Abidin Gülmüş isə zavod barədə məlumat verdi. Təməli 2023-cü il dekabrın 7-də qoyulan obyekt memorandum və ya plan deyil, fəaliyyətə başlamış istehsal müəssisəsidir. GEN KAP açıqlamasında onu Azərbaycanın ən böyük dərman istehsalı müəssisəsi adlandırıb.","Tərəfdaşlar — Rəsmi Azərbaycan mənbələrinə görə, müəssisənin 66%-i GEN İlaç ve Sağlık Ürünleri Sanayi A.Ş.-yə, 29%-i İqtisadiyyat Nazirliyi yanında Azərbaycan Biznesinin İnkişafı Fonduna, 5%-i isə Türkiyənin SIA Pharmaceuticals şirkətinə məxsusdur. Tərəfdaşlıq 2023-cü il iyulun 31-də GEN ilə Azərbaycan İnvestisiya Şirkəti (AİŞ) arasında imzalanan tərəfdaşlıq və birgə iştirak müqaviləsi ilə başlayıb; GEN-in KAP açıqlamasında da tərəfdaş kimi AİŞ göstərilir. Şirkət 2023-cü ildə Pirallahı Sənaye Parkının rezidenti statusunu alıb.","İnvestisiya — Layihənin ümumi dəyəri 113,9 milyon manatdır. Maliyyələşmə özəl investisiya, Azərbaycan Biznesinin İnkişafı Fondunun 13,2 milyon manatlıq investisiyası və 10 milyon manat güzəştli kreditdən ibarətdir. Interfax oktyabrın 5-nə olan məzənnə ilə (1 dollar = 1,70 manat) bu məbləği təxminən 67 milyon dollar kimi göstərib. Park rezidenti kimi şirkət 7 milyon manatdan çox ƏDV və gömrük rüsumundan azad olunub. Layihə ilkin plandan böyüyüb: 2023-cü ilin dekabrındakı təməlqoyma mərasimində investisiya 59,3 milyon manat, iş yerlərinin sayı isə 165 kimi açıqlanmışdı.","Gücü və iş yerləri — 5,2 hektar ərazidə yerləşən zavodun illik gücü 60 milyon qutu dərmandır, o cümlədən 2,5 milyard tablet və kapsul. Müəssisədə 178 daimi iş yeri var. Avadanlıqlar ABŞ, Yaponiya, Almaniya, İsveçrə, Çin, Danimarka, İsveç və Türkiyə istehsalçılarından alınıb. Zavodun Qarabağ Universiteti və Azərbaycan Tibb Universiteti üçün rəsmi tədris bazası olması da planlaşdırılır.","İstehsal olunan dərmanlar — Rəsmi məlumata görə, zavodda kardiologiya, nevrologiya, urologiya, diabetologiya və qastroenterologiya dərmanları, həmçinin ağrıkəsicilər və antibiotiklər istehsal olunacaq. Şirkət beş il ərzində 500-dən çox dərmanın istehsalını lokallaşdırmağı hədəfləyir; Türkiyə mətbuatının məlumatına görə, 2027-ci ilədək 50 dərmanın istehsala buraxılması planlaşdırılır. Məhsulların tam siyahısı açıqlanmayıb. GEN-in saytındakı Azərbaycan məhsulları səhifəsi (2025-ci ilin iyun arxiv nüsxəsində 27 məhsul) şirkətin bu ölkə üçün göstərdiyi məhsulları əks etdirir; bu, zavodun istehsal siyahısı deyil.","Bazar və ixrac — Baş direktor Fərid Əliyevin sözlərinə görə, prioritet daxili bazar və yerli tələbatın mümkün qədər tam ödənilməsidir. İxrac istiqamətləri kimi Özbəkistan, Qazaxıstan və Gürcüstan adlandırılıb. Pirallahı Sənaye Parkı əczaçılıq sənayesini inkişaf etdirmək və idxaldan asılılığı azaltmaq məqsədilə 2016-cı ildə Prezidentin fərmanı ilə yaradılıb; parkda altı rezident qeydiyyatdadır. CSC olaraq Azərbaycan bazarındakı bu inkişafları yaxından izləyirik.","Mənbə: APA (05.10.2026); Trend (05.10.2026); Report.az (05.10.2026); AZƏRTAC (05.10.2026); Borsagündem, GEN İlaç-ın KAP açıqlaması (05.10.2026); Interfax (06.10.2026); DHA (06.10.2026); Anadolu Agentliyi / Daily Sabah (07.12.2023); Trend (07.12.2023); Dövlət Vergi Xidməti, taxes.gov.az (31.07.2023); genilac.com.tr Azərbaycan məhsulları səhifəsi, Internet Archive arxivi (21.06.2025)."]}}'::jsonb) on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.blog_yazilari','id'), (select max(id) from public.blog_yazilari)); select count(*) as blog from public.blog_yazilari;
